            if($sources){$id=bin2hex(random_bytes(16));$text='برنامهٔ قاعده‌محور بازبینی وردپرس؛ پیشنهاد است و منتشر نشده است. تعداد کل: '.count($items)."\n";foreach(array_slice($items,0,100) as $item)$text.=$item['kind'].' #'.$item['id'].' '.$item['title']."\n".implode('؛ ',$item['issues'])."\n".$item['suggestion']."\n\n";$store=new AiStore();$store->putDocument($project['id'],$id,['title'=>'برنامهٔ بازبینی وردپرس','text'=>mb_substr($text,0,80000),'sources'=>$sources,'origin'=>'wordpress_rules','generated_at'=>gmdate(DATE_ATOM),'context'=>$context]);$owner=AiAccess::principal($project)['owner'];$store->transaction(function(&$s)use($project,$sources,$id,$owner){$s['reports'][$id]=['id'=>$id,'project'=>$project['id'],'owner'=>$owner,'title'=>'برنامهٔ بازبینی وردپرس','sources'=>$sources,'origin'=>'wordpress_rules','at'=>time()];});}
        }
    }
    public function principals(){ $out=[];foreach($this->store->read()['projects']??[] as $pid=>$state)if(!empty($state['principal']))$out[$pid]=$state['principal'];return $out; }
    public function opportunities($project,$gsc='',$ga4=''){
        $metrics=[];$hub=new AiHub(new AiStore());$from=date('Y-m-d',strtotime('-28 days'));$to=date('Y-m-d',strtotime('-1 day'));
        foreach(['gsc'=>$gsc,'ga4'=>$ga4] as $kind=>$sourceId){if($sourceId==='')continue;if(!ModuleProjectAccess::allowed('products','products','ai_connect','view')||!AiHub::canKind($kind))throw new RuntimeException('مجوز خواندن منبع تحلیلی را ندارید.');$offset=0;do{$page=$hub->read($project,$sourceId,$kind,['from'=>$from,'to'=>$to],$offset,500);foreach($page['rows'] as $r){$url=rtrim((string)($r['page']??$r['url']??''),'/');if($url==='')continue;foreach($kind==='gsc'?['clicks','impressions']:['sessions'] as $field)$metrics[$url][$field]=($metrics[$url][$field]??0)+(float)($r[$field]??0);}$offset=$page['next_offset'];}while($offset!==null);}
        $state=$this->state($project['id']);$out=[];foreach(['products','posts','pages','taxonomies'] as $kind){if($kind==='products'&&!canAccessFeature('products','view'))continue;$this->need($kind,'view');foreach($state['index'][$kind]??[] as $id=>$ref){if(!empty($ref['not_seen']))continue;$r=$this->store->document($project['id'],$ref['doc']);$at=!empty($r['modified_at'])?strtotime($r['modified_at']):false;$issues=[];if($at&&$at<time()-30*86400)$issues[]='بیش از ۳۰ روز بدون به‌روزرسانی';if(!$at)$issues[]='تاریخ ویرایش نامشخص';if(empty($r['seo_title']))$issues[]='عنوان سئو ندارد';if(empty($r['seo_description']))$issues[]='توضیحات سئو ندارد';$m=$metrics[rtrim($r['url']??'','/')]??[];if(($m['impressions']??0)>=100&&($m['clicks']??0)/$m['impressions']<0.02)$issues[]='نمایش جست‌وجو دارد؛ نرخ کلیک کمتر از ۲٪';if($issues)$out[]=['kind'=>$kind,'id'=>(string)$id,'title'=>$r['name']??$r['title']??'','url'=>$r['url']??'','modified_at'=>$r['modified_at']??null,'issues'=>$issues,'metrics'=>$m,'suggestion'=>!empty($m['impressions'])?'عنوان و توضیحات جست‌وجو و تطابق محتوا با قصد جست‌وجو بازبینی شود.':'اطلاعات محصول یا محتوای صفحه و متادیتای سئو بررسی و پیش‌نویس اصلاح آماده شود.'];}}return $out;
    }
    public function tick($project){if(!empty($project['settings']['backup_restore_paused']))return;if(empty($project['settings']['wordpress']['enabled']))return;$state=$this->state($project['id']);if(($state['last_tick']??0)>time()-60)return;$this->store->transaction(function(&$s)use($project){$s['projects'][$project['id']]['last_tick']=time();});try{
